-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 10
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 10 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 10', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 10 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-10.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Escreva, em ordem, as cinco etapas do processo fundamental de teste.', 0.2, '7.1 **Planejamento** → 7.2 **Desenho dos testes** → 7.3 **Execução** → 7.4 **Monitoração e controle** → 7.5 **Avaliação dos resultados**.', 'Palavras-chave: planejamento; desenho; execução; monitoração e controle; avaliação dos resultados, em ordem. Nota cheia (0,2): as cinco em ordem. Metade (0,1): as cinco fora de ordem, ou quatro em ordem. Zero (0): três ou menos.'),
      (v_atividade, 1, 2, 'Diga o que é feito no projeto da loja em cada uma das cinco etapas.', 0.4, '**Planejamento:** atualizar o plano e a matriz de rastreabilidade da SA 1. **Desenho:** escolher os casos por risco (caminho feliz e bordas). **Execução:** unitários (Vitest), integração (Testing Library + MSW) e E2E. **Monitoração e controle:** cobertura, testes instáveis e checks do pipeline. **Avaliação:** TESTING.md com resultado, fora do escopo e recomendação.', 'Palavras-chave: plano e matriz; casos por risco; três camadas; cobertura/flaky/checks; TESTING.md com recomendação. Nota cheia (0,4): as cinco etapas com o que é feito. Metade (0,2): três ou quatro etapas. Zero (0): duas ou menos.'),
      (v_atividade, 1, 3, 'Explique por que seguir as etapas em ordem evita começar a escrever testes sem saber o que é mais importante testar.', 0.4, 'O **planejamento e o desenho** vêm antes da execução: primeiro se decide **o que testar e em que ordem, pelo risco**, e só então se escrevem os testes. Sem isso, a equipe testa o que é **mais fácil** (e não o mais importante), gasta o tempo curto e chega ao fim **sem cobrir o que pode dar prejuízo**.', 'Palavras-chave: decidir antes o que testar; risco; testar o mais fácil em vez do mais importante. Nota cheia (0,4): explicação completa. Metade (0,2): "fica organizado" sem falar em prioridade. Zero (0): diz que a ordem não importa.'),
      (v_atividade, 2, 1, 'Diga o que vem primeiro, o que vem depois e o que fica fora do escopo.', 0.2, '**Primeiro:** a jornada **vitrine → carrinho → checkout → confirmação**. **Depois:** o **cupom**. **Fora do escopo:** a página **"Sobre nós"**.', 'Palavras-chave: jornada de compra primeiro; cupom depois; Sobre nós fora. Nota cheia (0,2): as três decisões. Metade (0,1): duas. Zero (0): ordem invertida ou sem fora do escopo.'),
      (v_atividade, 2, 2, 'Justifique pelo risco a ordem que você escolheu.', 0.4, 'A jornada de compra vem primeiro porque **é onde está o dinheiro**: se ela falhar na Black Friday, a loja **perde vendas**. O cupom vem depois porque é **onde estão os defeitos mais comuns** (validade, valor mínimo, valor fixo). A página "Sobre nós" fica fora porque um defeito nela tem **impacto baixo** e não impede a compra.', 'Palavras-chave: dinheiro/vendas na jornada; defeitos comuns no cupom; baixo impacto do Sobre nós. Nota cheia (0,4): as três justificativas pelo risco. Metade (0,2): duas. Zero (0): justificativa sem risco (ex.: "porque sim").'),
      (v_atividade, 2, 3, 'Escreva dois casos de teste do cupom: um do caminho feliz e um de borda, com entrada e resultado esperado.', 0.4, '**Caminho feliz:** total R$ 200,00 com cupom percentual de 10% válido → resultado esperado R$ 180,00. **Borda:** total exatamente igual ao valor mínimo do cupom (ex.: R$ 100,00 com mínimo R$ 100,00) → o cupom é aceito; ou cupom de valor fixo maior que o total → total R$ 0,00 (nunca negativo); ou cupom vencido → erro "Cupom expirado". (Valores diferentes valem, desde que coerentes.)', 'Palavras-chave: caso feliz com entrada e resultado; caso de borda (limite, valor fixo maior que o total, vencido) com entrada e resultado. Nota cheia (0,4): os dois casos com entrada e resultado esperado. Metade (0,2): só um caso, ou os dois sem resultado esperado. Zero (0): nenhum caso.'),
      (v_atividade, 3, 1, 'Diga quais ferramentas são usadas nos testes unitários, nos de integração e nos E2E.', 0.2, '**Unitários:** Vitest. **Integração:** Vitest com Testing Library e MSW (API simulada). **E2E:** Cypress ou Playwright.', 'Palavras-chave: Vitest; Testing Library + MSW; Cypress/Playwright. Nota cheia (0,2): as três camadas com as ferramentas. Metade (0,1): duas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 3, 2, 'Dê um exemplo da loja para cada camada (o que é testado em cada uma).', 0.4, '**Unitário:** regras como desconto, frete e cupom (ex.: aplicarCupom nunca deixa o total negativo). **Integração:** componentes como o carrinho e o checkout com a API simulada pelo MSW (ex.: carrinho mostra os itens; erro 500 mostra a mensagem). **E2E:** fluxos como login, compra completa e cupom inválido no navegador real.', 'Palavras-chave: regra/função no unitário; componente com API simulada na integração; fluxo completo no E2E. Nota cheia (0,4): um exemplo correto por camada. Metade (0,2): dois exemplos corretos. Zero (0): exemplos trocados de camada.'),
      (v_atividade, 3, 3, 'Explique, pela pirâmide de testes, por que a suíte tem mais testes unitários do que E2E.', 0.4, 'Pela **pirâmide**, os unitários ficam na **base**: são **rápidos e baratos** e apontam a função exata com erro, então podem ser muitos. Os E2E ficam no **topo**: são **lentos e mais frágeis**, por isso são **poucos**, só para os **fluxos críticos**.', 'Palavras-chave: base com muitos unitários rápidos; topo com poucos E2E lentos; fluxos críticos. Nota cheia (0,4): explicação dos dois lados da pirâmide. Metade (0,2): só um lado. Zero (0): pirâmide invertida.'),
      (v_atividade, 4, 1, 'Diga o que é uma suíte de testes organizada.', 0.2, 'É a suíte que **mostra a estratégia de testes só pela estrutura das pastas**: cada camada no seu lugar, com nomes claros, e os arquivos de configuração e documentação na raiz.', 'Palavras-chave: estratégia visível pela estrutura das pastas. Nota cheia (0,2): definição completa. Metade (0,1): "suíte arrumada" sem falar da estrutura. Zero (0): sem relação.'),
      (v_atividade, 4, 2, 'Escreva a estrutura de pastas e arquivos do repositório da loja com as pastas de testes, o workflow, a configuração e o TESTING.md.', 0.4, 'loja-virtual/ · src/ · tests/unitarios/ · tests/integracao/ · e2e/ · .github/workflows/ci.yml · vitest.config.js · TESTING.md (pode incluir package.json e playwright.config.js ou cypress.config.js).', 'Palavras-chave: src; tests/unitarios; tests/integracao; e2e; .github/workflows/ci.yml; vitest.config.js; TESTING.md. Nota cheia (0,4): estrutura completa. Metade (0,2): faltam dois itens ou as camadas não estão separadas. Zero (0): sem pastas de teste.'),
      (v_atividade, 4, 3, 'Explique o que fica em cada pasta de testes e por que separar as camadas ajuda a equipe.', 0.4, '**tests/unitarios:** as regras (descontos, frete, cupom). **tests/integracao:** os componentes (carrinho, checkout) com MSW. **e2e:** os fluxos (login, compra completa, cupom inválido). Separar ajuda a equipe a **achar o teste certo rápido**, a **rodar cada camada separada** (as rápidas a cada mudança, os E2E no pipeline) e a **ver o que falta** em cada camada.', 'Palavras-chave: regras nos unitários; componentes na integração; fluxos no e2e; achar e rodar cada camada. Nota cheia (0,4): conteúdo das pastas + vantagem. Metade (0,2): só uma das partes. Zero (0): conteúdo trocado.'),
      (v_atividade, 5, 1, 'Diga para que serve o bloco scripts do package.json.', 0.2, 'O bloco scripts guarda **comandos com nome** (npm test, npm run test:coverage…), para que **todos rodem a suíte do mesmo jeito**, no computador e no pipeline, sem decorar as opções.', 'Palavras-chave: comandos com nome; mesmo jeito para todos/no pipeline. Nota cheia (0,2): resposta completa. Metade (0,1): "guarda comandos" sem a vantagem. Zero (0): sem relação.'),
      (v_atividade, 5, 2, 'Escreva o bloco scripts com test, test:run, test:coverage e test:e2e.', 0.4, '"scripts": { "test": "vitest", "test:run": "vitest run", "test:coverage": "vitest run --coverage", "test:e2e": "playwright test" } (ou "cypress run" no test:e2e).', 'Palavras-chave: test vitest; test:run vitest run; test:coverage vitest run --coverage; test:e2e playwright test ou cypress run. Nota cheia (0,4): os quatro scripts. Metade (0,2): dois ou três. Zero (0): um ou nenhum.'),
      (v_atividade, 5, 3, 'Explique a diferença entre npm test (vitest) e npm run test:run (vitest run) e diga qual deles o pipeline deve usar.', 0.4, 'O **npm test (vitest)** fica em **modo observação**: roda de novo a cada arquivo salvo e **não termina** — bom para o desenvolvimento. O **npm run test:run (vitest run)** roda **uma vez e termina**, com sucesso ou erro. O pipeline deve usar o que **roda uma vez e termina** (test:run, ou test:coverage, que também usa vitest run), senão o job nunca acaba.', 'Palavras-chave: modo observação não termina; vitest run roda uma vez e termina; pipeline usa run/test:coverage. Nota cheia (0,4): diferença + escolha do pipeline. Metade (0,2): só uma das partes. Zero (0): manda o pipeline usar o modo observação.'),
      (v_atividade, 6, 1, 'Diga o mínimo de cobertura para aprovação e a meta Excelente.', 0.2, 'Mínimo para aprovação: **≥ 70%**; meta Excelente: **≥ 80%** (linhas, branches e funções).', 'Palavras-chave: 70%; 80%. Nota cheia (0,2): os dois valores. Metade (0,1): só um. Zero (0): valores errados.'),
      (v_atividade, 6, 2, 'Escreva, para testes unitários, integração, fluxos E2E e pipeline, o mínimo para aprovação e a meta Excelente.', 0.4, '**Unitários:** mínimo 5 casos; Excelente 10 ou mais, com bordas. **Integração:** mínimo o carrinho com API simulada; Excelente carrinho, carregamento e erro 500. **E2E:** mínimo 3 fluxos (login, compra completa, cupom inválido); Excelente os 3 estáveis em 3 execuções. **Pipeline:** mínimo executa a suíte; Excelente bloqueia o merge e tem badge.', 'Palavras-chave: 5/10 com bordas; carrinho com API simulada/carregamento e erro 500; 3 fluxos/estáveis em 3 execuções; executa/bloqueia merge e badge. Nota cheia (0,4): os quatro requisitos com mínimo e meta. Metade (0,2): dois ou três. Zero (0): um ou nenhum.'),
      (v_atividade, 6, 3, 'Explique por que a meta Excelente pede os 3 fluxos E2E estáveis em 3 execuções, e não só passando uma vez.', 0.4, 'Um teste que passa **uma vez** pode ser **instável (flaky)**: passar e falhar sem mudança no código. Exigir **3 execuções iguais** comprova que os fluxos são **confiáveis**, e só uma suíte confiável serve de **evidência** de que a loja pode ir para a Black Friday.', 'Palavras-chave: passar uma vez pode ser flaky; 3 execuções comprovam estabilidade; suíte confiável é evidência. Nota cheia (0,4): explicação completa. Metade (0,2): só define flaky. Zero (0): diz que passar uma vez basta.'),
      (v_atividade, 7, 1, 'Liste as cinco seções do TESTING.md.', 0.2, '**Como rodar**, **Estratégia**, **Fora do escopo**, **Resultado** e **Como contribuir**.', 'Palavras-chave: as cinco seções. Nota cheia (0,2): as cinco. Metade (0,1): três ou quatro. Zero (0): duas ou menos.'),
      (v_atividade, 7, 2, 'Escreva as seções Como rodar e Resultado com os dados da sua suíte.', 0.4, '**Como rodar:** npm ci (instalar), npm run test:coverage (unitários e integração com cobertura), npm run test:e2e (fluxos E2E, com a aplicação rodando). **Resultado:** cobertura final de 72%; 12 testes unitários, 4 de integração e 3 fluxos E2E estáveis em 3 execuções; 1 teste instável encontrado e corrigido (com a causa).', 'Palavras-chave: npm ci; npm run test:coverage; npm run test:e2e; 72%; quantidade por camada; teste instável registrado. Nota cheia (0,4): as duas seções completas com os dados. Metade (0,2): só uma seção, ou as duas sem os dados. Zero (0): nenhuma seção.'),
      (v_atividade, 7, 3, 'Escreva a seção Como contribuir e explique por que ela protege a suíte depois que você for embora.', 0.4, '**Como contribuir:** "Todo pull request precisa de **teste novo para o comportamento novo**; a suíte e a cobertura mínima precisam passar no CI antes do merge." Ela protege a suíte porque a **regra fica escrita** para quem chegar depois: o código novo **não entra sem teste**, e a cobertura não cai com o tempo.', 'Palavras-chave: teste novo para comportamento novo; regra escrita para quem vem depois; código sem teste não entra. Nota cheia (0,4): seção + explicação. Metade (0,2): só uma das partes. Zero (0): nenhuma.'),
      (v_atividade, 8, 1, 'Diga o que a seção Fora do escopo registra.', 0.2, '**O que não foi testado** e a **justificativa pelo risco** de cada item (S2).', 'Palavras-chave: o que não foi testado; justificativa pelo risco. Nota cheia (0,2): as duas partes. Metade (0,1): só a lista. Zero (0): sem relação.'),
      (v_atividade, 8, 2, 'Escreva a justificativa pelo risco para cada um dos dois itens que ficaram fora.', 0.4, '**Página "Sobre nós":** não foi testada porque é **conteúdo estático**, sem regra de negócio; um defeito nela tem **impacto baixo** e não impede a compra. **Integração real com a operadora de cartão:** não foi testada porque **depende de serviço externo**; o risco é **tratado com o mock (MSW) das respostas de recusa e de aprovação**.', 'Palavras-chave: Sobre nós estático/impacto baixo; operadora é serviço externo; risco tratado com mock de recusa e aprovação. Nota cheia (0,4): as duas justificativas pelo risco. Metade (0,2): só uma, ou as duas sem o risco. Zero (0): nenhuma justificativa.'),
      (v_atividade, 8, 3, 'Explique por que deixar algo fora do escopo, por escrito e justificado, é diferente de simplesmente esquecer de testar.', 0.4, 'Fora do escopo **por escrito e justificado** é uma **decisão consciente**: a equipe sabe o que não foi testado, **por que** e **como o risco foi tratado**, e pode testar depois se o risco mudar. Esquecer é **não saber** que existe um buraco na suíte — o risco fica **escondido** até virar defeito em produção.', 'Palavras-chave: decisão consciente; equipe sabe o que e por quê; esquecer esconde o risco. Nota cheia (0,4): os dois lados. Metade (0,2): só um lado. Zero (0): diz que é a mesma coisa.'),
      (v_atividade, 9, 1, 'Diga quais são os quatro itens do cartão de revisão.', 0.2, '**2 pontos fortes**, **1 risco** (teste instável, caso não coberto) e **1 sugestão**.', 'Palavras-chave: 2 pontos fortes; 1 risco; 1 sugestão. Nota cheia (0,2): os itens com as quantidades. Metade (0,1): itens sem as quantidades. Zero (0): itens errados.'),
      (v_atividade, 9, 2, 'Escreva o seu comentário no pull request com 2 pontos fortes, 1 risco e 1 sugestão.', 0.4, 'Exemplo: "**Pontos fortes:** 1) a suíte está separada por camadas e fácil de entender; 2) o fluxo de compra completa tem verificação em cada etapa. **Risco:** o teste E2E do checkout usa cy.wait(3000), que pode ficar instável numa máquina lenta. **Sugestão:** que tal trocar o cy.wait(3000) por cy.intercept com cy.wait(''@alias'') e acrescentar um teste de cupom vencido?" (Outros pontos fortes valem.)', 'Palavras-chave: dois pontos fortes concretos; risco da espera fixa ou do cupom vencido; sugestão técnica respeitosa. Nota cheia (0,4): os quatro itens concretos e respeitosos. Metade (0,2): falta um item, ou itens genéricos. Zero (0): comentário ofensivo ou sem os itens.'),
      (v_atividade, 9, 3, 'Explique como a dupla revisada deve responder a cada comentário e o que fazer com uma sugestão que ela decidir não aplicar.', 0.4, 'A dupla revisada responde **a cada comentário** com **"aceito, porque…"** ou **"mantenho, porque…"**, sempre com **fato técnico** (S1). A sugestão que ela decidir **não aplicar** é **registrada no TESTING.md** com o motivo.', 'Palavras-chave: responder a cada comentário; aceito porque/mantenho porque; fato técnico; registrar no TESTING.md. Nota cheia (0,4): forma de responder + registro. Metade (0,2): só uma das partes. Zero (0): manda ignorar os comentários.'),
      (v_atividade, 10, 1, 'Diga os três instrumentos da avaliação da UC e o peso de cada um.', 0.2, '**Avaliação contínua** (entregas das aulas 1 a 9 e SAs 1 e 2): **60%**. **Avaliação prática** (suíte de testes para a aplicação fornecida): **25%**. **Avaliação objetiva** (conceitos, técnicas, tipos e processo de teste): **15%**.', 'Palavras-chave: contínua 60%; prática 25%; objetiva 15%. Nota cheia (0,2): os três com os pesos. Metade (0,1): instrumentos sem os pesos ou pesos trocados. Zero (0): nenhum correto.'),
      (v_atividade, 10, 2, 'Calcule a nota final, mostrando a conta, e diga se você está aprovado e por quê.', 0.4, 'Nota final = 0,60 × 8,0 + 0,25 × 9,0 + 0,15 × 6,0 = 4,80 + 2,25 + 0,90 = **7,95**. **Aprovado**, porque a nota final é **≥ 7,0** e a presença de **80%** é maior que o mínimo de **75%**.', 'Palavras-chave: conta com os pesos; 7,95; nota ≥ 7,0; presença ≥ 75%. Nota cheia (0,4): conta certa + aprovação com os dois critérios. Metade (0,2): conta certa sem citar a presença, ou erro de conta com o raciocínio certo. Zero (0): pesos errados e sem critério de aprovação.'),
      (v_atividade, 10, 3, 'Explique o parecer por capacidade (Desenvolvida, Em desenvolvimento ou Não desenvolvida) e escreva um exemplo de evidência do seu repositório para a capacidade C5.', 0.4, 'Além da nota, **cada capacidade** (C1 a C5, S1 e S2) recebe o parecer **Desenvolvida**, **Em desenvolvimento** ou **Não desenvolvida**, e o estudante cita uma **evidência do próprio repositório**. Exemplo para C5 (desenvolver conjunto de testes automatizados): "Desenvolvida — o pull request da suíte tem 12 testes unitários, 4 de integração e 3 fluxos E2E, com o workflow verde e 72% de cobertura."', 'Palavras-chave: parecer por capacidade com os três níveis; evidência concreta do repositório para C5. Nota cheia (0,4): explicação + evidência concreta. Metade (0,2): só uma das partes, ou evidência vaga ("fiz os testes"). Zero (0): nenhuma.');
end $$;
